# Define function square(n) returning n*n.
def square(n):
    """
    Returns the square of a given number n.

    Args:
        n (int): The number to calculate the square of.

    Returns:
        int: The square of n.
    """
    return n * n

# Test the function
print(square(5))  # Output: 25
print(square(0))  # Output: 0
print(square(-5))  # Output: 25
print(square(10))  # Output: 100
print(square(100))  # Output: 10000
print(square(10000))  # Output: 